@Test
  public void trimExcessBlankLines() {
    String[] test = new String[] {
        "",
        "",
        sentence,
        "",
        "",
        sentence,
        "",
        ""
    };

    String[] expected = new String[] {
        "",
        sentence,
        "",
        sentence,
        ""
    };

    assertArrayEquals(expected, StringHelper.trimExcessBlankLines(test));

    assertNull(StringHelper.trimExcessBlankLines(null));
  }

